-- Messrunde 10c-4a -- Sitzung 3: M149 (Z-U) und M150 (Z-D), die Zerlegung des Boesfalls
-- Auftrag:  "Prozessansicht -- freies Zeitfenster, Messrunde (Schritt 10c-4a)",
--           Stand 07.09.2026
-- Ergebnis: docs/process-view.md Paragraf 30 ff.
--
-- ERZEUGT von scripts/messung-prozessansicht-frei/erzeuge.py. Der Statementtext
-- kommt aus scripts/messung-prozessansicht/gerendert.txt (M116, aus
-- ProzessbaumRepository gefallen) und ist NUR in Ebene und Bereichspraedikat
-- variiert.
--
-- Ausschliesslich SELECT / SET / EXPLAIN. (Regel S1) Benutzer monitor_read.
-- G1: keine Zugangsdaten, kein Hostname. Mandanten-IDs sind Codes.
-- L9: SET max_statement_time = 60. Jedes Statement, das die Grenze reisst, ist
--     eine Abweichung vom Rahmen und wird als solche ausgewiesen.
--
-- Z1: Alle Fenster enden auf 2025-12-30 03:00:00 -- unterhalb des Dev-Ankers
--     2025-12-30 04:09:47, auf einer Stundengrenze, im dichten Bestand.
--
-- ZWECK. Der Boesfall 2024-12-29 14:00 -> 2025-12-30 03:00 in fuenf
-- Abschnitten: 10 Stunden, 2 Tage, 11 Monate, 29 Tage, 3 Stunden = 55
-- Zeitscheiben. Zwei Bauformen:
--   M149 = Z-U: EIN Statement, die drei Bereichslesungen als UNION ALL in
--          einer Ableitung, darauf eine Gruppierung und die Mandantenkette.
--   M150 = Z-D: DREI Statements, eines je Ebene; Stunde und Tag tragen je
--          zwei Bereiche (Kopf und Fuss). Ausgewiesen wird die Summe der drei
--          SQL-Laufzeiten. Die Summierung in Java und die zwei zusaetzlichen
--          Umlaeufe sind NICHT enthalten -- das ist die Luecke dieser Zahl.
-- Vorregistriert: beide unter 100 ms (Erwartung 4), Z-U langsamer als Z-D
-- (Erwartung 6, wegen der Ableitung aus M114 mit 98 bis 398 ms).

SELECT '=== 00 read_only (erste Abfrage der Sitzung) ===' AS marke;
SELECT @@global.read_only AS read_only, NOW() AS serverzeit, VERSION() AS version,
       @@max_statement_time AS grenze_vorher;

SET max_statement_time = 60;
SET profiling = 1;
SET profiling_history_size = 100;

SELECT '=== M149-ZU-NEXANS · Plan (Regel L15) ===' AS marke;
EXPLAIN select `t`.`process_id`, `t`.`message_status`, sum(`t`.`anzahl`) from (select `overlord_monitor`.`message_rollup`.`process_id`, `overlord_monitor`.`message_rollup`.`message_status`, `overlord_monitor`.`message_rollup`.`anzahl` from `overlord_monitor`.`message_rollup` where ((`overlord_monitor`.`message_rollup`.`stunde` >= timestamp '2024-12-29 14:00:00.0' and `overlord_monitor`.`message_rollup`.`stunde` < timestamp '2024-12-30 00:00:00.0') or (`overlord_monitor`.`message_rollup`.`stunde` >= timestamp '2025-12-30 00:00:00.0' and `overlord_monitor`.`message_rollup`.`stunde` < timestamp '2025-12-30 03:00:00.0')) union all select `overlord_monitor`.`message_rollup_tag`.`process_id`, `overlord_monitor`.`message_rollup_tag`.`message_status`, `overlord_monitor`.`message_rollup_tag`.`anzahl` from `overlord_monitor`.`message_rollup_tag` where ((`overlord_monitor`.`message_rollup_tag`.`tag` >= date '2024-12-30' and `overlord_monitor`.`message_rollup_tag`.`tag` < date '2025-01-01') or (`overlord_monitor`.`message_rollup_tag`.`tag` >= date '2025-12-01' and `overlord_monitor`.`message_rollup_tag`.`tag` < date '2025-12-30')) union all select `overlord_monitor`.`message_rollup_monat`.`process_id`, `overlord_monitor`.`message_rollup_monat`.`message_status`, `overlord_monitor`.`message_rollup_monat`.`anzahl` from `overlord_monitor`.`message_rollup_monat` where `overlord_monitor`.`message_rollup_monat`.`monat` >= date '2025-01-01' and `overlord_monitor`.`message_rollup_monat`.`monat` < date '2025-12-01') as `t` where exists (select 1 as `one` from `GlassfishDB`.`Process` as `baum_process` join `GlassfishDB`.`ProjectMandant` on `GlassfishDB`.`ProjectMandant`.`ProjectID` = `baum_process`.`ProjectID` where (`baum_process`.`ProcessID` = `t`.`process_id` and `GlassfishDB`.`ProjectMandant`.`MandantID` = 'NEXANS')) group by `t`.`process_id`, `t`.`message_status`;
