SELECT 'M150-ZD-SUTTONS' AS fall, ebene,
       COUNT(*)                             AS anzahl_laeufe,
       MAX(CASE WHEN runde = 1 THEN ms END) AS aufwaermlauf,
       MIN(CASE WHEN runde > 1 THEN ms END) AS beste_von_fuenf,
       GROUP_CONCAT(CASE WHEN runde > 1 THEN ms END ORDER BY runde) AS alle_fuenf
FROM (SELECT ELT(((rn - 1) MOD 3) + 1, 'stunde', 'tag', 'monat') AS ebene,
       FLOOR((rn - 1) / 3) + 1 AS runde, ms
FROM (SELECT ROW_NUMBER() OVER (ORDER BY QUERY_ID) AS rn,
             ROUND(SUM(DURATION) * 1000, 3) AS ms
      FROM information_schema.PROFILING
      WHERE QUERY_ID > @basis + 1 AND QUERY_ID <= @basis + 1 + 18
      GROUP BY QUERY_ID) t) u
GROUP BY ebene ORDER BY FIELD(ebene, 'stunde', 'tag', 'monat');
SELECT 'M150-ZD-SUTTONS' AS fall, 'summe_je_runde' AS ebene,
       COUNT(*)                             AS anzahl_runden,
       MAX(CASE WHEN runde = 1 THEN ms END) AS aufwaermlauf,
       MIN(CASE WHEN runde > 1 THEN ms END) AS beste_von_fuenf,
       GROUP_CONCAT(CASE WHEN runde > 1 THEN ms END ORDER BY runde) AS alle_fuenf
FROM (SELECT runde, ROUND(SUM(ms), 3) AS ms FROM (SELECT ELT(((rn - 1) MOD 3) + 1, 'stunde', 'tag', 'monat') AS ebene,
       FLOOR((rn - 1) / 3) + 1 AS runde, ms
FROM (SELECT ROW_NUMBER() OVER (ORDER BY QUERY_ID) AS rn,
             ROUND(SUM(DURATION) * 1000, 3) AS ms
      FROM information_schema.PROFILING
      WHERE QUERY_ID > @basis + 1 AND QUERY_ID <= @basis + 1 + 18
      GROUP BY QUERY_ID) t) u
      GROUP BY runde) r;

